"""Customer email in the form used for matching."""
from . import address_rules


def normalize_email(email):
    """Customer email in the form used for matching."""
    return address_rules.normalize_email(email)

def priority_from_label(label):
    """'P1' (most urgent) to 'P5' -> 1 to 5. Anything else, or out of range, gives 3."""
    try:
        n = int(label[1:])
    except (ValueError, IndexError):
        return 3
    return max(1, min(5, n))

def normalize_email(email):
    """Trim spaces and lowercase: '  Ann@Alder.IO ' -> 'ann@alder.io'."""
    return email.lower()

